(function(){
  const form=document.querySelector('#order-form'); if(!form)return;
  const estimate=document.querySelector('#estimate'),status=document.querySelector('#order-status');
  function payload(){const data=new FormData(form);return{firstName:data.get('firstName'),contactEmail:data.get('contactEmail'),braceletStyle:data.get('braceletStyle'),quantity:Number(data.get('quantity')||1),colors:[data.get('color1'),data.get('color2'),data.get('color3')].filter(Boolean),charm:data.get('charm'),nameWord:data.get('nameWord'),size:data.get('size'),neededBy:data.get('neededBy'),giftPackaging:data.get('giftPackaging')==='on',notes:data.get('notes'),consent:data.get('consent')==='on'};}
  function update(){const d=payload();if(!d.braceletStyle){estimate.textContent='Choose a style to estimate.';return;}let base=d.braceletStyle==='braided'?600:d.braceletStyle==='mixed'?1600:800;let total=base*d.quantity;if(d.nameWord)total+=200*d.quantity;if(d.charm&&d.braceletStyle!=='braided')total+=200*d.quantity;if(d.giftPackaging)total+=200;estimate.textContent=`$${(total/100).toFixed(2)} starting estimate before shipping or marketplace fees.`;}
  form.addEventListener('input',update);update();
  form.addEventListener('submit',async event=>{event.preventDefault();status.className='status';status.textContent='Sending request…';try{const response=await fetch('/api/orders',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload())});const data=await response.json();if(!response.ok)throw new Error((data.details||[data.error]).join(' '));status.className='status success';status.textContent=`Request received. Reference: ${data.order.id}. An adult-managed CharmNest contact will confirm the details.`;form.reset();update();}catch(error){status.className='status error';status.textContent=error.message;}});
})();
